import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text());done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[
 dict(parent='12487',gloss=['cold'],languages=['Tor','Bshk'],forms=['śīdal','śīdāl'],citation='CDIAL[12487]',evidence='Turner explicitly lists Torwali šidul alongside Pashai šidāl, Palula šidālo and Shina šidălu under śītala, marking the medial d unexplained. The Torwali/Bashkarik survey śīdal forms fit this particular northwestern d-bearing family; that unresolved consonant history is retained rather than called regular.'),
 dict(parent='12629',gloss=['broom'],languages=['jaun','Goj'],forms=['çuyaṇa','suyaṇ','suyiṇ','suiṇ','sun'],citation='CDIAL[12629]',evidence='The full śodhana article has Prakrit sohaṇī broom and specifically Jaunsari śuain, with Kotgarhi śv̄̃ṇ and J. śū̃hṇ in the addendum. These whole broom forms match that regional contraction; the Jaunsari form with extra ṭ is excluded. Gujari sun is compared with Hindi sonī and Punjabi sūhnī, with regional contact left open.'),
 dict(parent='43',gloss=['eye'],languages=['Kho','Gaw','Tor','Mai','Chil','Gowro','bhatr','Goj'],forms=['xɛcʰ','xɛc','xic','yīʦīn','æṣī','akʰ / ākʰ','ā̃ʦ̣i / ā̃c','ā̃cī / ā̃c','āʦ̣ī / āʦ̣','ā̃ʦ̣','āʦ̣','ā̃ṣ','ʦ̣','c'],citation='CDIAL[43]',evidence='Turner’s full akṣi entry names Khowar γeč(h), Gawri iċīn, Torwali aṣī and Maiya āc̣hī/ãc̣hī, as well as Punjabi/Lahnda akkh. These survey forms match the named regional affricate/sibilant series, including reduced vowels and alternative spellings of the same eye stem. Turner’s unexplained Khowar initial γ is preserved as an uncertainty; slash responses are included only when both members fit this family.'),
 dict(parent='43',gloss=['eye'],languages=['Bhatri','AdivasiOriya','hal','Bhili','kaithal','mewari_basad'],forms=['anki','aĩk','ãki','aki','ākhyo','ãnk','ākī','ā̃kī','akī','æk','aŋk'],citation='CDIAL[43]',evidence='Turner lists Oriya ākhi/āẽkha, Bengali ã̄kh(i), Hindi ã̄kh and Gujarati ã̄kh under akṣi. These simple survey eye forms retain the diagnostic velar outcome, with nasalization, final agreement and source aspiration notation varying. The assignment is to the comparative eye family; unusual prefixed or further extended forms are excluded rather than normalized.'),
 dict(parent='7031-2',gloss=['nose'],languages=['Chil','Gowro'],forms=['notʰū','notʰī'],citation='CDIAL[7031,2]',evidence='The nastaka subsection explicitly gives Kandia natho and Shina Kohistani notŭ for nose. Chilis/Gowro nothū/nothī matches this local nath-/noth- stem and final-vowel variation, rather than the nāsā or nāsikā families; the separate Torwali plural-looking nɔthɛ̃ is left for morphological review.'),
 dict(parent='4272',gloss=['leg'],forms=['goḍɨ','goḍa','gɔḍɨ','gūḍū','gūṛ','guḍu','gvarā'],citation='CDIAL[4272]',evidence='Turner’s *gōḍḍa family explicitly covers foot, leg and knee, with Hindi goṛ/goṛā, Oriya goṛa and Kumaoni gwāṛo foot; the addendum records Kacchi gūḍo knee. The survey leg forms retain this whole regional stem, with retroflex stop/flap and rounded-vowel variation; suffix-bearing goḍek is excluded.'),
 dict(parent='4701-2',gloss=['skin'],forms=['cāmbḍɔ','sāmaḍā','sāmaḍa','samḍī','samaro','sāmuṛɔ','sāmoḍo'],citation='CDIAL[4701,extension ḍa]',evidence='Turner explicitly separates the ḍa extension of carman and lists Gujarati cāmḍũ/cāmḍī and Marathi cāmḍẽ/cāmḍī hide/skin. The western survey forms fit this extended family, with s for c and retroflex flap/stop variants retained; cāmbḍɔ includes the transitional labial stop in the mḍ cluster. The specific attested extension is used, not the separately inferred generic ḍ node.'),
 dict(parent='5228',gloss=['tongue'],languages=['Majhi','Bote','bagheli_lakshman'],forms=['jiβi','jibi','jībī'],citation='CDIAL[5228,1]',evidence='Turner’s jihvā branch includes Prakrit jibbhā, Bengali jib, Bhojpuri jībhī and Nepali jib(h)ro. These whole jiβi/jibi/jībī tongue forms preserve the regional j-b labial sequence and feminine final vowel; expanded n-bearing forms and Persian zabān-like responses are excluded.'),
 dict(parent='11165',gloss=['blood'],languages=['Kho','kaithal'],forms=['le','lav'],citation='CDIAL[11165]',evidence='Turner’s addendum explicitly gives Khowar lei blood; the main entry gives Lahnda/Punjabi lahū/lohū and broader lo-/lau outcomes. Khowar le and Kaithali lav fit this contracted blood family, with the final glide retained. Multiword and slash responses containing another blood stem are not collapsed into this assignment.'),
 dict(parent='9188',gloss=['broom'],languages=['kul'],forms=['buārə'],citation='CDIAL[9188]',evidence='Turner gives Punjabi buhārā/bahārī and Prakrit baühārī/bōhārī broom under bahukāra. Kullu buārə matches the neighboring whole broom formation with loss of intervocalic h; the link leaves local Punjabi contact open. Other broom responses lacking enough consonantal material to distinguish bahukāra from vardhana are excluded.'),
]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms'] and ('languages' not in g or r['Language_ID'] in g['languages']):a.append(dict(record=r,parent=g['parent'],kind='reflex',citation=g['citation'],evidence=g['evidence'],family=i))
assert len(a)==len({x['record']['ID'] for x in a})
h=[dict(record=r,reason='Turner 958 explicitly labels these Nuristani/Dardic aṭhī-type bone words as loans from Indic. The remote aṣṭhi node would skip the immediate donor, which has not been established for this survey variety.') for r in rs if r['ID'] not in done and r['Gloss']=='bone' and r['Form'] in ['aṭʰī','āṭʰī','ā̃ṭʰī','anṭʰī']]
(P/'pass021-decisions.json').write_text(json.dumps(dict(accepted=a,held=h),ensure_ascii=False,indent=1)+'\n')
(P/'pass021-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
print(len(a),'accepted',len(h),'held',[(g['parent'],sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
